// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address caller, uint128 depositAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);
        vm.prank(caller);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }
        require(ok, "withdraw failed unexpectedly");
        assertTrue(c.balances(caller) == 0);
    }
}
